(async () => {
  // Test data typed by hand (E2E only): the world cards the look step needs, because the fixture
  // model answers only "Hello." and so never writes them. Saved through the app's own IPC.
  const list = await window.seed.createDrafts.list();
  if (!list.ok) return list;
  const entry = list.value.find((e) => e.kind !== "broken" && JSON.stringify(e).includes("A river delta"));
  const id = entry?.draftId ?? entry?.draft?.draftId;
  const read = await window.seed.createDrafts.read(id);
  if (!read.ok) return read;
  const d = read.value;
  d.world = {
    fields: {
      premise: "A river delta where lantern keepers trade salt for stories.",
      tone: "Quiet, warm, a little wistful.",
      rules: ["Lanterns are never left dark.", "Salt pays for every story."],
      taboos: ["No one crosses the delta at night without a lantern."],
      naming: "Short names taken from boats and tides.",
      voice: "Plain speech with river sayings.",
      look: "Reed-roofed stilt houses, paper lanterns, grey-green water, low evening light.",
    },
    edited: ["premise", "tone", "rules", "taboos", "naming", "voice", "look"],
    basis: { name: d.idea.name, intent: d.idea.intent, material: d.idea.story, language: d.idea.language, fights: d.idea.play.fights },
    rev: 1,
  };
  d.step = "look";
  const saved = await window.seed.createDrafts.save(d);
  return saved.ok ? { draftId: saved.value.draftId, step: saved.value.step, look: saved.value.world.fields.look } : saved;
})()

